import React, { useState } from 'react';
import styled from 'styled-components';
import { size } from '../device';
import { timeline } from '../data/content';

import img1877 from '../assets/timeline-imgs/1877.png';
import img1933 from '../assets/timeline-imgs/1933.png';
import img1968 from '../assets/timeline-imgs/1968.png';
import img1983 from '../assets/timeline-imgs/1983.png';
import img1988 from '../assets/timeline-imgs/1988.png';
import img2004 from '../assets/timeline-imgs/2004.png';
import img2024 from '../assets/timeline-imgs/2024.png';

const IMAGES = { '1877': img1877, '1933': img1933, '1968': img1968, '1983': img1983, '1988': img1988, '2004': img2004, '2024': img2024 };
const VISIBLE = 3;
const MAX_INDEX = timeline.length - VISIBLE;

const Section = styled.section`
  background-color: #faf8f5;
  padding: 5rem 0 4rem;
  overflow: hidden;
`;

const Inner = styled.div`
  max-width: 760px;
  margin: 0 auto;
  padding: 0 2rem;
`;

const Heading = styled.h2`
  font-family: 'Bitter', serif;
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 700;
  color: #1c1c1c;
  margin: 0 0 2.5rem;
  text-decoration: underline;
  text-decoration-color: #7ecff4;
  text-decoration-thickness: 3px;
  text-underline-offset: 0.2em;
`;

const CarouselOuter = styled.div`
  position: relative;
  max-width: 760px;
  margin: 0 auto;
  padding: 0 2rem;
`;

const ArrowButton = styled.button`
  position: absolute;
  top: 0.5rem;
  ${({ side }) => side === 'left' ? 'right: calc(100% - 2rem + 1.5rem);' : 'left: calc(100% - 2rem + 1.5rem);'}
  background: none;
  border: none;
  cursor: pointer;
  color: ${({ disabled }) => disabled ? 'rgba(28,28,28,0.2)' : '#1c1c1c'};
  padding: 0;
  display: flex;
  align-items: center;
  transition: color 0.2s;

  &:hover:not(:disabled) {
    color: #7ecff4;
  }
`;

const TrackOuter = styled.div`
  overflow: hidden;
`;

const Track = styled.div`
  display: flex;
  width: ${(timeline.length / VISIBLE) * 100}%;
  transition: transform 0.4s ease;
`;

const SlideItem = styled.div`
  flex: 0 0 calc(100% / ${timeline.length});
  text-align: center;
  padding: 0 0.75rem;
`;

const Year = styled.div`
  font-family: 'Bitter', serif;
  font-size: clamp(1.5rem, 2.5vw, 2rem);
  font-weight: 700;
  color: #7ecff4;
  margin-bottom: 0.6rem;
`;

const ItemDivider = styled.div`
  height: 1px;
  background-color: #1c1c1c;
  margin: 0 -0.75rem;
`;

const EventText = styled.p`
  font-family: 'Open Sans', sans-serif;
  font-size: 0.82rem;
  line-height: 1.55;
  color: #1c1c1c;
  margin: 0.65rem 0 0.75rem;
  min-height: 2.5em;
`;

const EventImage = styled.img`
  width: 100%;
  aspect-ratio: 3 / 4;
  object-fit: cover;
  display: block;
`;

const Dots = styled.div`
  display: flex;
  justify-content: center;
  gap: 0.4rem;
  margin-top: 1.5rem;
`;

const Dot = styled.button`
  width: 7px;
  height: 7px;
  border-radius: 50%;
  border: none;
  cursor: pointer;
  padding: 0;
  background-color: ${({ active }) => (active ? '#1c1c1c' : 'rgba(28,28,28,0.2)')};
  transition: background-color 0.2s;
`;

const TimelineCarousel = () => {
  const [startIndex, setStartIndex] = useState(0);

  const prev = () => setStartIndex(i => Math.max(0, i - 1));
  const next = () => setStartIndex(i => Math.min(MAX_INDEX, i + 1));

  return (
    <Section id="timeline">
      <Inner>
        <Heading>150 Years of Spectator</Heading>
      </Inner>

      <CarouselOuter>
        <ArrowButton side="left" onClick={prev} disabled={startIndex === 0} aria-label="Previous">
          <svg width="18" height="52" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.25" strokeLinecap="round" strokeLinejoin="round">
            <polyline points="15 18 9 12 15 6" />
          </svg>
        </ArrowButton>

        <TrackOuter>
          <Track style={{ transform: `translateX(-${startIndex * (100 / timeline.length)}%)` }}>
            {timeline.map((item) => (
              <SlideItem key={item.year}>
                <Year>{item.year}</Year>
                <ItemDivider />
                <EventText>{item.event}</EventText>
                {item.image && (
                  <EventImage src={IMAGES[item.image]} alt={item.event} />
                )}
              </SlideItem>
            ))}
          </Track>
        </TrackOuter>

        <ArrowButton side="right" onClick={next} disabled={startIndex === MAX_INDEX} aria-label="Next">
          <svg width="18" height="52" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.25" strokeLinecap="round" strokeLinejoin="round">
            <polyline points="9 18 15 12 9 6" />
          </svg>
        </ArrowButton>
      </CarouselOuter>

      <Dots>
        {Array.from({ length: MAX_INDEX + 1 }).map((_, i) => (
          <Dot key={i} active={i === startIndex} onClick={() => setStartIndex(i)} aria-label={`Go to position ${i + 1}`} />
        ))}
      </Dots>
    </Section>
  );
};

export default TimelineCarousel;
